import math

# Range for t
t_range = range(-5, 6)

equations = {
    "Eq1: z^3 = 8t^3 - 65": 65,
    "Eq2: z^3 = 8t^3 - 13": 13,
    "Eq3: z^3 = 8t^3 - 5": 5,
    "Eq4: z^3 = 8t^3 - 1": 1
}

results = {}

for name, C in equations.items():
    solutions = []
    print(f"\n--- Testing {name} ---")
    for t in t_range:
        V = 8 * (t**3) - C

        # Check if V is a perfect cube
        if V == 0:
            z = 0
            is_perfect_cube = True
        else:
            # Calculate the cube root and round to the nearest integer
            z_candidate = round(abs(V)**(1/3))

            # Check if z_candidate^3 equals |V|
            if z_candidate**3 == abs(V):
                # Determine the sign of z
                if V > 0:
                    z = z_candidate
                else:
                    z = -z_candidate
                is_perfect_cube = True
            else:
                is_perfect_cube = False

        if is_perfect_cube:
            solutions.append((t, z))
            print(f"Found solution: t={t}, z={z}. Check: {z}^3 = {z**3}, 8t^3 - {C} = {V}")

    results[name] = solutions

print("\n--- Summary ---")
for name, solutions in results.items():
    if solutions:
        print(f"{name} has solutions: {solutions}")
    else:
        print(f"{name} has no solutions in the range |t| <= 5.")
